package com.nigson.commerce.fulfillment;
import java.util.*;
import java.time.*;
import java.nio.ByteBuffer;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.inventory.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
public final class ShipmentService {
 private final ShipmentRepository repository;private final StockLedger stock;private final InventoryAuthority authority;private final PlatformStore commands;private final AuditWriter audit;private final JdbcTemplate jdbc;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public ShipmentService(ShipmentRepository repository,StockLedger stock,InventoryAuthority authority,PlatformStore commands,AuditWriter audit,JdbcTemplate jdbc,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.repository=repository;this.stock=stock;this.authority=authority;this.commands=commands;this.audit=audit;this.jdbc=jdbc;this.clock=clock;this.metrics=metrics;}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,Object body,UUID correlation,java.util.function.Supplier<PlatformStore.Response> change){authority.require(actor);ApiValues.idempotencyKey(key);if(correlation==null)throw ApiValues.invalid();ApiValues.uuid(correlation.toString());try{return commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),db->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");authority.stabilize(actor);return change.get();});}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private void evidence(ActorAssertion.Actor actor,AuditValues.Action action,AuditValues.Resource resource,UUID id,Long before,long after,UUID correlation,String operation){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,resource,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,before==null?null:Map.of("version",before),Map.of("version",after),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.fulfillment.commands","operation",operation).increment();}});}
 private void event(ActorAssertion.Actor actor,FulfillmentValues.Shipment shipment,UUID correlation,boolean booking){Instant time=clock.instant();var body=new LinkedHashMap<String,Object>();body.put("event_id",EventCodec.uuid7(time));body.put("event_type",booking?"shipment.booking.requested.v1":"shipment.changed.v1");body.put("schema_version",1);body.put("producer","commerce");body.put("occurred_at",time);body.put("aggregate_id",shipment.id());body.put("aggregate_version",shipment.version());body.put("organization_id",repository.organization(shipment.orderId()));body.put("correlation_id",correlation);body.put("traceparent",null);if(booking){UUID request=jdbc.queryForObject("SELECT booking_request_id FROM commerce.shipment WHERE id=?",UUID.class,shipment.id());body.put("payload",Map.of("shipment_id",shipment.id(),"booking_request_id",request,"provider","FEDEX"));}else body.put("payload",Map.of("shipment_id",shipment.id(),"order_id",shipment.orderId(),"status",shipment.status(),"occurred_at",time));commands.append(EventCodec.JSON.writeValueAsString(body),actor.party().toString());}
 public FulfillmentValues.Shipment create(ActorAssertion.Actor actor,UUID order,FulfillmentValues.ShipmentInput input,String key,UUID correlation){authority.require(actor);repository.organization(order);var response=execute(actor,"API-048",key,Map.of("order",order,"body",input),correlation,()->{var after=repository.create(order,input,actor.party().toString());evidence(actor,AuditValues.Action.SHIPMENT_CREATE,AuditValues.Resource.SHIPMENT,after.id(),null,after.version(),correlation,"SHIPMENT");repository.event(after.id(),after.id(),after.status(),clock.instant(),actor.party().toString());event(actor,after,correlation,false);if(input.provider().equals("FEDEX"))event(actor,after,correlation,true);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),after.id());});return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Shipment.class);}
 public FulfillmentValues.Shipment dispatch(ActorAssertion.Actor actor,UUID id,long expected,String reason,String key,UUID correlation){authority.require(actor);repository.find(id,false);var response=execute(actor,"API-049",key,Map.of("id",id,"version",expected,"reason",reason),correlation,()->{var after=repository.dispatch(id,expected,actor.party().toString());try{stock.dispatch(after.orderId(),repository.stockLines(id),id,actor.party().toString(),correlation);}catch(Problem.Failure failure){if(failure.getMessage().equals("INVENTORY_RULE_VIOLATION"))throw FulfillmentValues.rule();throw failure;}repository.progress(after.orderId(),actor.party().toString());UUID command=stable(Map.of("shipment",id,"operation","DISPATCH"));repository.event(id,command,"SHIPPED",clock.instant(),actor.party().toString());evidence(actor,AuditValues.Action.SHIPMENT_DISPATCH,AuditValues.Resource.SHIPMENT,id,expected,after.version(),correlation,"DISPATCH");event(actor,after,correlation,false);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),id);});return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Shipment.class);}
 public FulfillmentValues.Shipment delivered(ActorAssertion.Actor actor,UUID id,long expected,FulfillmentValues.Delivery input,String key,UUID correlation){authority.require(actor);repository.find(id,false);var response=execute(actor,"API-050",key,Map.of("id",id,"version",expected,"body",input),correlation,()->{var after=repository.delivered(id,expected,input,actor.party().toString());repository.progress(after.orderId(),actor.party().toString());repository.event(id,stable(Map.of("shipment",id,"operation","DELIVERY")),"DELIVERED",input.deliveredAt(),actor.party().toString());evidence(actor,AuditValues.Action.SHIPMENT_DELIVERY,AuditValues.Resource.SHIPMENT,id,expected,after.version(),correlation,"DELIVERY");event(actor,after,correlation,false);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),id);});return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Shipment.class);}
 private static UUID stable(Object identity){byte[] digest=java.util.HexFormat.of().parseHex(EventCodec.hash(EventCodec.JSON.valueToTree(identity)));digest[6]=(byte)((digest[6]&15)|128);digest[8]=(byte)((digest[8]&63)|128);var bytes=ByteBuffer.wrap(digest);return new UUID(bytes.getLong(),bytes.getLong());}
 public FulfillmentValues.Return returned(ActorAssertion.Actor actor,UUID order,FulfillmentValues.ReturnInput input,String key,UUID correlation){authority.require(actor);repository.organization(order);ApiValues.idempotencyKey(key);String receipt=input.receiptReference();if(receipt==null)receipt="UNSHIPPED:"+stable(Map.of("actor",actor.party(),"key",key,"order",order));final String evidenceReceipt=receipt;UUID command=stable(Map.of("order",order,"kind",input.kind(),"receipt",receipt));var response=execute(actor,"API-174",key,Map.of("order",order,"body",input),correlation,()->{repository.lockOrder(order);boolean previous=commands.completed("local-stock-ledger","STOCK-RETURN",command.toString());try{stock.returned(order,input.lines().stream().map(l->new StockLedger.Line(l.orderLineId(),l.balanceId(),l.quantity())).toList(),input.kind(),evidenceReceipt,input.reason(),command,actor.party().toString(),correlation);}catch(Problem.Failure failure){if(failure.getMessage().equals("INVENTORY_RULE_VIOLATION"))throw FulfillmentValues.rule();throw failure;}var after=new FulfillmentValues.Return(command,order,input.lines().stream().sorted(Comparator.comparing(l->l.orderLineId().toString())).map(l->new FulfillmentValues.ShipmentLine(l.orderLineId(),l.quantity())).toList());if(!previous)evidence(actor,AuditValues.Action.STOCK_RETURN,AuditValues.Resource.ORDER,order,null,jdbc.queryForObject("SELECT version FROM commerce.sales_order WHERE id=?",Long.class,order),correlation,"RETURN");return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),command);});return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Return.class);}
}
